update vm_alarm_device_suppress
alarm_suppress_id = #{alarmSuppressId,jdbcType=INTEGER}, device_code = #{deviceCode,jdbcType=VARCHAR}, tenant_id = #{tenantId,jdbcType=VARCHAR}, creater_by = #{createrBy,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=TIMESTAMP}, update_by = #{updateBy,jdbcType=VARCHAR}, update_time = #{updateTime,jdbcType=TIMESTAMP}, delete_flag = #{deleteFlag,jdbcType=VARCHAR},
where device_id=#{deviceId}

mapper.select:
		SELECT device_id,
		alarm_suppress_id,
		device_code,
		tenant_id,
		creater_by,
		create_time,
		update_by,
		update_time,
		delete_flag
		FROM vm_alarm_device_suppress
		WHERE delete_flag = 0
		 and device_id = #{deviceId,jdbcType=INTEGER}
		 and alarm_suppress_id = #{alarmSuppressId,jdbcType=INTEGER}
		 and device_code = #{deviceCode,jdbcType=VARCHAR}
		 and tenant_id = #{tenantId,jdbcType=VARCHAR}
		 and creater_by = #{createrBy,jdbcType=VARCHAR}
		 and create_time = #{createTime,jdbcType=TIMESTAMP}
		 and create_time BETWEEN #{startDate} and #{endDate}
		 and update_by = #{updateBy,jdbcType=VARCHAR}
		 and update_time = #{updateTime,jdbcType=TIMESTAMP}
		 and delete_flag = #{deleteFlag,jdbcType=VARCHAR}
		 and alarm_suppress_id in

				#{strategyId}




				order by create_time asc


				order by create_time desc


				order by update_time asc


				order by update_time desc


              order by device_id desc
